import math

def check_good(x, y, z):
    # Calculate (x+1)^y and x^z + 1
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Check if the division results in an integer
    return numerator % denominator == 0

# --- Case x = 1 ---
# Expected: All 99*99 = 9801 are solutions.
count_x1 = 0
for y in range(1, 100):
    for z in range(1, 100):
        # We know mathematically this must always be true: 2^y / 2 = 2^(y-1)
        if check_good(1, y, z):
            count_x1 += 1

print(f"Count for x=1: {count_x1}")

# --- Case x = 2 ---
# Expected: 197 solutions (z=1, y=1..99; z=3, y=2..99)
