for y in range(1, 100):
    for z in range(1, 100):
        if check_good(2, y, z):
            count_x2 += 1

print(f"Count for x=2: {count_x2}")

# --- Case x = 3 ---
# Expected: 99 solutions (z=1, y=1..99)
