for y in range(1, 100):
    for z in range(1, 100):
        if check_good(3, y, z):
            count_x3 += 1

print(f"Count for x=3: {count_x3}")

def solve():
    count = 0
    # Constraints: 1 <= x, y, z <= 99
    for x in range(1, 100):
        for y in range(1, 100):
            for z in range(1, 100):
                # Check if (x^z + 1) divides (x+1)^y

                # Numerator: (x+1)^y
                numerator = (x + 1)**y

                # Denominator: x^z + 1
                denominator = x**z + 1

                # Since x, y, z >= 1, both numerator and denominator are positive integers.

                if numerator % denominator == 0:
                    count += 1
    return count

print(solve())
